#!/usr/bin/env python3
"""rep.py fixture field,field 'cmd'...: print only the given fields of the reply for each command (run alone)."""
import json, sys, subprocess, tempfile, shutil, os
exe = os.environ.get('EXE', '/workspace/executable')
src = sys.argv[1]; fields = sys.argv[2].split(',')
for c in sys.argv[3:]:
    d = tempfile.mkdtemp(prefix='r')
    shutil.copy(src, os.path.join(d, 'in.bimcraft'))
    p = subprocess.run([exe, 'run', 'in.bimcraft', '--cmd', c], cwd=d, capture_output=True, text=True)
    lines = p.stdout.splitlines()[1:]
    print('#', c)
    if p.stderr.strip(): print('  ERR', p.stderr.strip()[:500])
    for l in lines:
        try:
            v = json.loads(l)
            print('  ', {f: v.get(f, '<absent>') for f in fields})
        except Exception:
            print('  >', l[:300])
    shutil.rmtree(d)

