#!/usr/bin/env python3
"""summ.py ft_out.txt [category]: compact per-field signatures."""
import sys, re
lines = open(sys.argv[1]).read().splitlines()
want = sys.argv[2] if len(sys.argv) > 2 else None
cur = None; field = None; res = {}
def sig(field, res):
    # derive type signature
    def short(s):
        s = s.replace('E: invalid type: ', '')
        s = re.sub(r'^(string "x"|floating point `1.5`|integer `5`|integer `-1`|boolean `true`|null|sequence|map), expected ', 'exp ', s)
        return s[:140]
    exp = set()
    out = []
    for pv, r in res:
        s = short(r)
        if s.startswith('exp '):
            exp.add(s[4:])
        else:
            out.append('%s=>%s' % (pv, s))
    return '%-18s [%s] %s' % (field, '|'.join(sorted(exp)), ' ; '.join(out))
for l in lines:
    if l.startswith('== '):
        if field and (not want or cur == want): print('  ' + sig(field, res))
        field = None
        cur = l.split()[1]
        if not want or cur == want:
            print(l[:400])
    elif l.startswith('-- '):
        if field and (not want or cur == want): print('  ' + sig(field, res))
        field = l[3:]; res = []
    elif l.startswith('   '):
        pv = l[3:20].strip(); r = l[20:].strip()
        res.append((pv, r))
if field and (not want or cur == want): print('  ' + sig(field, res))

