#!/usr/bin/env python3
"""cat.py cmd...: print catalog docs of the given commands (truncated)."""
import sys
lines = open('/tmp/edit-agent/catalog.txt').read().splitlines()
n = 900
args = sys.argv[1:]
if args and args[0].startswith('-n'):
    n = int(args[0][2:]); args = args[1:]
for c in args:
    for i, l in enumerate(lines):
        if l.startswith('## %s | ' % c):
            print(l)
            print(lines[i + 1][:n])

