#!/usr/bin/env python3
"""cmpb.py [-v] fixture 'cmd' ...  (or -f casefile with lines 'fixture<TAB>cmd'): run each command alone on the
fixture with the original and mine (`run in.bimcraft --cmd CMD --save out.bimcraft`), compare stdout, stderr,
exit code and the saved file, normalised as cmp.py does. Prints SAME/DIFF per case and a summary."""
import os, re, subprocess, sys, tempfile, shutil, difflib, json
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a739f1ca2cb873f93/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)
def run(exe, fx, cmds, extra):
    d = tempfile.mkdtemp(prefix='cb')
    shutil.copy(fx, os.path.join(d, 'in.bimcraft'))
    args = [exe, 'run', 'in.bimcraft']
    for c in cmds:
        args += ['--cmd', c]
    args += extra + ['--save', 'out.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, text=True, timeout=120)
    f = None
    if os.path.exists(os.path.join(d, 'out.bimcraft')):
        f = open(os.path.join(d, 'out.bimcraft')).read()
    shutil.rmtree(d)
    return p.returncode, p.stdout, p.stderr, f
def compare(fx, cmds, verbose, extra=[]):
    o = run(ORIG, fx, cmds, extra)
    m = run(MINE, fx, cmds, extra)
    diffs = []
    for name, x, y in (('code', o[0], m[0]), ('stdout', o[1], m[1]), ('stderr', o[2], m[2]), ('file', o[3] or '', m[3] or '')):
        a = norm(str(x)); b = norm(str(y))
        if a != b:
            dl = list(difflib.unified_diff(a.splitlines(), b.splitlines(), 'orig', 'mine', lineterm='', n=1))[2:]
            diffs.append((name, dl))
    return diffs
def main():
    a = sys.argv[1:]
    verbose = False; cases = []; extra = []
    while a and a[0].startswith('-'):
        if a[0] == '-v': verbose = True; a = a[1:]
        elif a[0] == '-f':
            for l in open(a[1]):
                l = l.rstrip('\n')
                if not l or l.startswith('#'): continue
                fx, c = l.split('\t', 1)
                cases.append((fx, c.split('\t')))
            a = a[2:]
        elif a[0] == '-e': extra.append(a[1]); a = a[2:]
        else: break
    if a:
        fx = a[0]
        for c in a[1:]:
            cases.append((fx, [c]))
    nd = 0
    for fx, cmds in cases:
        diffs = compare(fx, cmds, verbose, extra)
        label = ' | '.join(cmds)
        if not diffs:
            print('SAME', os.path.basename(fx), label[:200])
        else:
            nd += 1
            print('DIFF', os.path.basename(fx), label[:200])
            for name, dl in diffs:
                print('   ---', name)
                for l in dl[:(60 if verbose else 12)]:
                    print('     ', l[:400])
    print('== %d cases, %d differ' % (len(cases), nd))
main()

