278	/// A struct from a map (its keys in name order) or a sequence (its fields in order).
279	pub fn de_struct(pr: &Project, v: &Value, sd: &Sd) -> Result<(), String> {
280	    match v {
281	        Value::Obj(m) => {
282	            let mut items: Vec<&(String, Value)> = m.items.iter().collect();
283	            items.sort_by(|a, b| a.0.cmp(&b.0));
284	            let names: Vec<&str> = sd.fields.iter().map(|f| f.name).collect();
285	            for (k, x) in items {
286	                match sd.fields.iter().find(|f| f.name == k) {
287	                    Some(f) => de(pr, x, &f.t)?,
288	                    None if sd.deny => return Err(unknown_field(k, &names)),
289	                    None => {}
290	                }
291	            }
292	            for f in sd.fields {
293	                if f.required && !m.contains(f.name) {
294	                    return Err(format!("missing field `{}`", f.name));
295	                }
296	            }
297	            Ok(())
298	        }
299	        Value::Arr(a) => {
300	            for (i, f) in sd.fields.iter().enumerate() {
301	                match a.get(i) {
302	                    Some(x) => de(pr, x, &f.t)?,
303	                    None if f.required => {
304	                        return Err(format!(
305	                            "invalid length {}, expected struct {} with {} elements",
