n = len(pts)
def offline(a, b, t):
    dx, dy = b[0] - a[0], b[1] - a[1]
    l = math.hypot(dx, dy)
    nx, ny = -dy / l, dx / l
    return (a[0] + nx * t, a[1] + ny * t), (dx, dy)
def offline2(a, b, t):
    dx, dy = b[0] - a[0], b[1] - a[1]
    l = math.sqrt(dx * dx + dy * dy)
    nx, ny = -dy / l * t, dx / l * t
    return (a[0] + nx, a[1] + ny), (dx, dy)
def offline3(a, b, t):
    dx, dy = b[0] - a[0], b[1] - a[1]
    l = math.sqrt(dx * dx + dy * dy)
    ux, uy = dx / l, dy / l
    return (a[0] - uy * t, a[1] + ux * t), (ux, uy)
def inter(p1, d1, p2, d2):
