import math, itertools
pts = [(0.0, 0.0), (5000.0, 1000.0), (4000.0, 5000.0), (-500.0, 4000.0)]
want = [[85.8835834826835, 119.15710696839233], [4877.549773134886, 1077.4903448988327], [3926.6094574387876, 4881.251607683173], [-389.48667001083913, 3922.1191349165683]]
t = 100.0
n = len(pts)
def normals():
    def hyp(a, b):
        dx, dy = b[0] - a[0], b[1] - a[1]; l = math.hypot(dx, dy); return (-dy / l, dx / l)
    def sq(a, b):
        dx, dy = b[0] - a[0], b[1] - a[1]; l = math.sqrt(dx * dx + dy * dy); return (-dy / l, dx / l)
    def ang(a, b):
        th = math.atan2(b[1] - a[1], b[0] - a[0]); return (-math.sin(th), math.cos(th))
    def ang2(a, b):
        th = math.atan2(b[1] - a[1], b[0] - a[0]) + math.pi / 2; return (math.cos(th), math.sin(th))
    return {'hyp': hyp, 'sq': sq, 'ang': ang, 'ang2': ang2}
def dirs():
    def raw(a, b): return (b[0] - a[0], b[1] - a[1])
    def unit(a, b):
        dx, dy = b[0] - a[0], b[1] - a[1]; l = math.hypot(dx, dy); return (dx / l, dy / l)
    def angd(a, b):
        th = math.atan2(b[1] - a[1], b[0] - a[0]); return (math.cos(th), math.sin(th))
    return {'raw': raw, 'unit': unit, 'angd': angd}
def inters():
    def i1(p1, d1, p2, d2):
        c = d1[0] * d2[1] - d1[1] * d2[0]
        s = ((p2[0] - p1[0]) * d2[1] - (p2[1] - p1[1]) * d2[0]) / c
        return (p1[0] + s * d1[0], p1[1] + s * d1[1])
    def i2(p1, d1, p2, d2):
        c = d1[0] * d2[1] - d1[1] * d2[0]
        u = ((p2[0] - p1[0]) * d1[1] - (p2[1] - p1[1]) * d1[0]) / c
        return (p2[0] + u * d2[0], p2[1] + u * d2[1])
    def i3(p1, d1, p2, d2):
        # line eq a x + b y = c
        a1, b1 = d1[1], -d1[0]; c1 = a1 * p1[0] + b1 * p1[1]
        a2, b2 = d2[1], -d2[0]; c2 = a2 * p2[0] + b2 * p2[1]
        det = a1 * b2 - a2 * b1
        return ((c1 * b2 - c2 * b1) / det, (a1 * c2 - a2 * c1) / det)
    def i4(p1, d1, p2, d2):
        # two-point form: q1 = p1 + d1
        x1, y1 = p1; x2, y2 = p1[0] + d1[0], p1[1] + d1[1]
        x3, y3 = p2; x4, y4 = p2[0] + d2[0], p2[1] + d2[1]
        den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
        px = ((x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4)) / den
        py = ((x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4)) / den
        return (px, py)
    return {'i1': i1, 'i2': i2, 'i3': i3, 'i4': i4}
best = []
for (nn, nf), (dn, df), (iname, it) in itertools.product(normals().items(), dirs().items(), inters().items()):
    for start_end in ('start', 'end'):
        res = []
        for i in range(n):
            a, b, c = pts[i - 1], pts[i], pts[(i + 1) % n]
            n1 = nf(a, b); n2 = nf(b, c)
            base1 = a if start_end == 'start' else b
            base2 = b if start_end == 'start' else c
            p1 = (base1[0] + n1[0] * t, base1[1] + n1[1] * t)
            p2 = (base2[0] + n2[0] * t, base2[1] + n2[1] * t)
            res.append(it(p1, df(a, b), p2, df(b, c)))
        score = sum(1 for i in range(n) if list(res[i]) == want[i])
        err = max(abs(res[i][0] - want[i][0]) + abs(res[i][1] - want[i][1]) for i in range(n))
        best.append((score, -err, nn, dn, iname, start_end))
best.sort(reverse=True)
for b in best[:8]:
    print(b)

