cases = [(90, 4000), (60, 4000), (-60, 4000), (30, 4000), (120, 4000), (45, 2000)]
data = {c: json.load(open('/tmp/edit-modify/arcroom_%d_%d.json' % c))['centre']['outer'] for c in cases}
def centres(s, e, a):
    dx, dy = e[0] - s[0], e[1] - s[1]
    out = {}
    L = math.hypot(dx, dy); L2 = math.sqrt(dx * dx + dy * dy)
    for ln, l in (('hyp', L), ('sqrt', L2)):
        n = (-dy / l, dx / l); m = ((s[0] + e[0]) / 2, (s[1] + e[1]) / 2)
        h = l / (2 * math.tan(a / 2))
        out['mid_tan_' + ln] = (m[0] + n[0] * h, m[1] + n[1] * h)
        h2 = (l / 2) / math.tan(a / 2)
        out['mid_tan2_' + ln] = (m[0] + n[0] * h2, m[1] + n[1] * h2)
        r = l / (2 * math.sin(a / 2)); hh = math.sqrt(max(r * r - (l / 2) ** 2, 0)) * (1 if (abs(a) < math.pi) == (a > 0) else -1)
        out['mid_sqrt_' + ln] = (m[0] + n[0] * hh, m[1] + n[1] * hh)
    return out
def radii(s, e, a, c):
    dx, dy = e[0] - s[0], e[1] - s[1]; L = math.hypot(dx, dy)
